body.css:
body {
    overflow: hidden !important;
}

.cf_overlay_1439_3320 :focus {
    outline: 1px #1965e1 dotted;
    outline-offset: 2px;
}

.cf_overlay_1439_3320 .cf-container-shim {
    position: fixed;
    z-index: 999999;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    margin: auto;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    background: rgba(0, 0, 0, 0.4);
}

.cf_overlay_1439_3320 .cf-container {
    position: absolute;
    top: 10%;
    right: 0;
    left: 0;
    margin: auto;
    height: 50%;
    width: 420px;
    box-sizing: border-box;
    border-radius: 5px;
}

.cf_overlay_1439_3320 .cf-container * {
    box-sizing: inherit;
}

.cf_overlay_1439_3320 .cf-container__content {
    background: #fff;
    box-shadow: 0 0 16px #ccc;
    width: 100%;
    height: 100%;
    border-radius: 5px;
}

.cf_overlay_1439_3320 .cf-container__close {
    position: absolute;
    top: 14px;
    right: 14px;
    width: 22px;
    height: 22px;
    background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' width='14' height='14' viewBox='0 0 14 14'%3e%3cline x1='0' y1='0' x2='14' y2='14' stroke='%23FFF' stroke-width='2' /%3e%3cline x1='0' y1='14' x2='14' y2='0' stroke='%23FFF' stroke-width='2' /%3e%3c/svg%3e ");
    background-repeat: no-repeat;
    background-position: center;
    background-color: transparent;
    border: none;
    cursor: pointer;
}

.cf_overlay_1439_3320 .cf-container__frame {
    display: block;
    width: 100%;
    height: 100%;
    border: none;
    border-radius: 5px;
}

@keyframes cf_overlay_1439_3320_id__loader-animation {
    0% {
        opacity: 0;
    }

    50% {
        opacity: .8;
    }

    100% {
        opacity: 0;
    }
}

.cf_overlay_1439_3320 .cf-container__loader {
    position: absolute;
    left: 0;
    top: -5vh;
    right: 0;
    bottom: 0;
    width: 100px;
    height: 50px;
    margin: auto;
}

.cf_overlay_1439_3320 .cf-loader__items {
    font-size: 60px;
    display: inline-flex;
    align-items: center;
}

.cf_overlay_1439_3320 .cf-loader__item {
    animation: cf_overlay_1439_3320_id__loader-animation 1.8s infinite;
    animation-play-state: inherit;
    border-radius: 50%;
    opacity: 0;
    width: .4em;
    height: .4em;
    background: #777;
}

.cf_overlay_1439_3320 .cf-loader__item:nth-child(1) {
    animation-delay: 0s;
}

.cf_overlay_1439_3320 .cf-loader__item:nth-child(2) {
    animation-delay: .3s;
    margin: 0.6ex;
}

.cf_overlay_1439_3320 .cf-loader__-item:nth-child(3) {
    animation-delay: .6s;
}

.cf_overlay_1439_3320[data-auto-height] .cf-container {
    height: auto;
}

.cf_overlay_1439_3320[data-auto-height] .cf-container__content {
    margin-bottom: 5vh;
}

.cf_overlay_1439_3320[data-auto-height] .cf-container__frame {
    height: 400px;
    transition: height 0.5s ease;
}

@media (max-width:640px), (max-height: 640px) {
    .cf_overlay_1439_3320 .cf-container {
        position: absolute;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        width: 100%;
        height: 100%;
    }
}

.cf_invite_1439_3149 :focus {
    outline: 1px #0d2ea0 dotted;
    outline-offset: 3px;
}

.cf_invite_1439_3149 .cf-survey-prompt {
  box-sizing: border-box;
  transform: rotate(-90deg) translateY(123px);
  transform-origin: left bottom;
}

.cf_invite_1439_3149 .cf-survey-prompt {
  position: fixed;
  z-index: 999999;
  font: 14px Arial;
  //background: #0d2ea0;
  border-radius: 5px;
}


.cf_invite_1439_3149 .cf-survey-prompt--accept:hover {
  color: rgb(230, 230, 230);
}

.cf_invite_1439_3149 .cf-survey-prompt--accept {
  -webkit-appearance: none;
  border: none;
  display: inline-block;
  border-radius: 5px;
  color: white;
  text-align: center;
  padding: 4px 23px;
  line-height: normal;
  height: 34px;
  cursor: pointer;
  font-family: helvetica, arial;
  font-size: 14px;
}

.cf_invite_1439_3149 .cf-survey-prompt--accept {
  background-color: #0d2ea0;
  border: 1px solid #fff;
}

.cf_invite_1439_3149 .cf-survey-prompt--middle-right {
  right: 0px;
  top: 50%;
}

