#mcp-toast-c .mcp-toast-container {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    margin: auto;
    transform: translateY(0);
    transition: transform 0.3s ease-in-out;
    will-change: transform;
    height: 160px;
    width: 70%;
    min-width: 900px;
    z-index: 100001;
    font-size: 1rem;
    display: flex;
}

#mcp-toast-c #mcp-tab {
    text-align: center;
    padding: 5px;
    width: 340px;
    cursor: pointer;
    position: absolute;
    left: 46%;
    margin-left: -137.5px;
    bottom: 160px;
    font-size: 18px;
}

#mcp-toast-c .mcp-card {
    text-size-adjust: auto;
    scroll-snap-align: start;
}

#mcp-overlay {
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    opacity: .3;
    width: 100%;
    height: 100%;
    background-color: #000;
    z-index: 10000;
}

#mcp-toast-c .mcp-arrow.mcp-up {
    transform: rotate(-135deg);
}

.mcp-card-container {
    display: flex;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    padding: 5px;
    height: 100%;
    width: 100%;
    justify-content: space-between;
}

.mcp-card-content {
    padding: 5px 15px 15px 15px;
    height: 100%;
    width: 100%;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    text-size-adjust: auto;
}

#mcp-toast-c .mcp-hidden {
    transform: translateY(calc(100% - 0px));
}

.mcp-hidden_toast {

  opacity: 0;
  transform: translateY(-10px);
  transition: opacity 0.25s ease, transform 0.25s ease;
  pointer-events: none;
}

.mcp-cta-container,
#mcp-signUp {
    width: 100%;
    margin-top: auto;
}

.mcp-input-group {
    display: flex;
    width: 100%;
}

