}

.signUp-3 .mcp-heading,
.signUp-2 .mcp-heading {
    margin-top: 0px;
}

.signUp-1 .mcp-card-content {
    flex-flow: row wrap !important;
}
.signUp-1 .mcp-text-content {
    width: 50% !important;
    display: table-cell !important;
    vertical-align: center !important;
    margin-top: 20px !important;
    padding: 10px;
}
.signUp-1 #mcp-signUp {
    width: 50% !important;
    display: table-cell !important;
    vertical-align: center !important;
    margin-top: 40px;
    padding: 10px;
}

.CTA .mcp-cta-container {
    width: 100%;
    margin-top: auto;
}

.CTA .mcp-cta {
    padding: 5px 20px !important;
