                    Animations
*************************************************/
@keyframes slide-in-right {
  0% {
    /*transform: translateX(100%);*/
    opacity: 0;
  }
  100% {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes slide-in-left {
  0% {
    /*transform: translateX(-100%);*/
    opacity: 0;
  }
  100% {
    transform: translateX(0);
    opacity: 1;
  }
}

.slide-in-right {
  animation: slide-in-right .5s ease-out forwards;
}

.slide-in-left {
  animation: slide-in-left .5s ease-out forwards;
}

@keyframes hide-then-show {
  0% {
    opacity: 0;
  }
  50% {
    opacity: 0;
  }
  99% {
      opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

.hide-then-show {
  animation: hide-then-show 0.5s linear;
}
