    /* =========================================================

       EMAIL CAPTURE

    ========================================================== */

   function setupEmailCapture(context) {
    const form   = document.querySelector("#mcp-email-form");
    const input  = document.querySelector("#mcp-contact-detail");
    const button = document.querySelector("#mcp-submit-signUp");

    // If user already has a Customer ID, the form won't be in the DOM — exit early
    if (!input) {
        console.log("ℹ️ No email input found — user may already be signed up.");
        return;
    }

    function isValidEmail(email) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    }

    function showInvalidEmailMessage() {
        const msgBox = document.getElementById("messageBox");
        if (!msgBox) return;
        msgBox.innerHTML = '<p class="mcp-error">Please enter a valid email address.</p>';
    }

    function clearMessageBox() {
        const msgBox = document.getElementById("messageBox");
        if (msgBox) msgBox.innerHTML = "";
    }

    function setSigningUpState(btn) {
        if (!btn) return;
        btn.disabled = true;
        btn.textContent = "Signing up...";
        btn.classList.add("mcp-disabled");
    }

    function showConfirmation() {
        const msgBox = document.getElementById("mcp_text_content");
        const signUpForm = document.getElementById("mcp-signUp");
        const messageBox = document.getElementById("messageBox");

        if (signUpForm) signUpForm.style.display = "none";
        if (messageBox) messageBox.style.display = "none";

        if (msgBox) {
            msgBox.innerHTML = 
                '<h3 class="mcp-heading" style="margin:5px 0 5px 0; color: #0429A1">Thank you for signing up!</h3>' +
                '<p class="mcp-msg_thank">You\'ll receive an email shortly with exclusive offers and deals.</p>';
        }
    }

    function sendEmailEvent(email) {
        if (!isValidEmail(email)) {
            console.warn("⚠️ Invalid email — event not sent:", email);
            return;
        }

        const event = {
            interaction: { name: "Email Sign Up" },
            user: {
                identities: { emailAddress: email },
                attributes: { emailAddress: email, toastSignupCompleted: true }
            }
        };

        SalesforceInteractions.sendEvent(event);
        console.log("✅ Email captured and event sent:", email);
    }

    function handleSubmit(e) {
        e.preventDefault();
        const email = input.value.trim();

        if (!isValidEmail(email)) {
            showInvalidEmailMessage();
            return;
        }

        clearMessageBox();
        setSigningUpState(button);

        // Fire the Salesforce Interactions event for triggered campaign segmentation
        sendEmailEvent(email);

        // Show confirmation message
        showConfirmation();
    }

    // Bind to form submit if it exists
    if (form) {
        form.addEventListener("submit", handleSubmit);
    }

    // Bind to button click as well
    if (button) {
        button.addEventListener("click", handleSubmit);
    }
}


    /* =========================================================

       MOBILE CARD SWITCHING

    ========================================================== */

    function setupMobileCards(context) {
        var currentCard = 0;
        var cards = document.querySelectorAll('#mcp-toast-c .mcp-card');
        var leftArrow = document.getElementById('mcp-tab-left');
        var rightArrow = document.getElementById('mcp-tab-right');

        if (!cards.length) return;

        function isMobile() {
            return window.innerWidth <= (context.switchToMobilePx || 800);
        }

        function updateCards() {
            if (!isMobile()) {
                // Desktop — show all cards, remove mobile classes, hide arrows
                cards.forEach(function(card) {
                    card.classList.remove('mcp-mobile-active', 'mcp-mobile-inactive');
                });
                if (leftArrow) leftArrow.classList.add('hide-tab');
                if (rightArrow) rightArrow.classList.add('hide-tab');
                return;
            }

            // Mobile — show only the current card
            cards.forEach(function(card, index) {
                if (index === currentCard) {
                    card.classList.add('mcp-mobile-active');
                    card.classList.remove('mcp-mobile-inactive');
                } else {
                    card.classList.add('mcp-mobile-inactive');
                    card.classList.remove('mcp-mobile-active');
                }
            });

            // Show/hide arrows based on position
            if (leftArrow) {
                if (currentCard > 0) leftArrow.classList.remove('hide-tab');
                else leftArrow.classList.add('hide-tab');
            }
            if (rightArrow) {
                if (currentCard < cards.length - 1) rightArrow.classList.remove('hide-tab');
                else rightArrow.classList.add('hide-tab');
            }
        }

        if (leftArrow) {
            leftArrow.addEventListener('click', function() {
                if (currentCard > 0) {
                    currentCard--;
                    updateCards();
                }
            });
        }

        if (rightArrow) {
            rightArrow.addEventListener('click', function() {
                if (currentCard < cards.length - 1) {
                    currentCard++;
                    updateCards();
                }
            });
        }

        // Initial setup
        updateCards();

        // Re-evaluate on resize
        window.addEventListener('resize', updateCards);
    }


    /* =========================================================

       TEMPLATE HOOKS

    ========================================================== */

    function apply(context, template) {

        return Evergage.DisplayUtils.pageElementLoaded("body").then((element) => {

            // Prevent duplicate rendering
            if (document.getElementById('mcp-toast-c')) {
                return;
            }

            const html = template(context);

            console.log("context email in apply:", context.emailAddress);
            console.log("context hasCustomerId:", context.hasCustomerId);

            Evergage.cashDom(element).append(html);

            overlayClick();

            toggleListener(context);

            const overlay = document.querySelector("#mcp-overlay");

            if (overlay) overlay.classList.toggle('hidden');
            // Check if user dismissed the toast this session
            var toastDismissed = false;
            try {
                toastDismissed = sessionStorage.getItem('mcpToastDismissed') === 'true';
            } catch(e) { }

            if (context.startOpen && !context.hasCustomerId && !context.toastSignupCompleted && !toastDismissed) document.querySelector("#mcp-tab").click();

            if (context.autoOpen && !context.hasCustomerId && !context.toastSignupCompleted && !toastDismissed) {
                console.log("context.openAfterSeconds:", context.openAfterSeconds);
                setTimeout(() => { document.querySelector("#mcp-tab").click(); }, context.openAfterSeconds * 1000);
            }

            // Initialize email capture (will no-op if user already has Customer ID)
            setupEmailCapture(context);

            // Initialize mobile card switching
            setupMobileCards(context);

        });

    }

    function reset(context, template) {

        document.querySelectorAll("#mcp-toast-c").forEach(t => t.remove());

        Evergage.cashDom("#mcp-tab").remove();

    }

    function control(context) {

        const contentZoneSelector = Evergage.getContentZoneSelector(context.contentZone);

        return Evergage.DisplayUtils.pageElementLoaded(contentZoneSelector).then((element) => {

            Evergage.cashDom(element).attr({

                "data-evg-campaign-id": context.campaign,

                "data-evg-experience-id": context.experience,

                "data-evg-user-group": context.userGroup

            });

        });

    }

    registerTemplate({

        apply: apply,

        reset: reset,

        control: control

    });

})();

