    /* =========================================================

       PATCH: Ensure email identity is always set on sendEvent

    ========================================================== */

    const originalSendEvent = SalesforceInteractions.sendEvent;

    SalesforceInteractions.sendEvent = function(event) {

        if (event && event.user) {

            const emailAttr = event.user.attributes?.emailAddress;

            // If only attributes.emailAddress is set, copy it into identities

            if (emailAttr && (!event.user.identities || !event.user.identities.emailAddress)) {

                event.user.identities = event.user.identities || {};

                event.user.identities.emailAddress = emailAttr;

                console.log("🔧 Fixed payload: added email identity", emailAttr);

            }

        }

        return originalSendEvent.call(SalesforceInteractions, event);

    };

