    function toggleListener(context) {

        document.querySelector("#mcp-tab").addEventListener('click', () => {
            const toastContainer = document.getElementById('mcp-toastContainer');
            const arrow = document.getElementById('mcp-arrow');
            const overlay = document.querySelector("#mcp-overlay");

            toastContainer.classList.toggle('mcp-hidden');
            arrow.classList.toggle('mcp-up');
            if (overlay) overlay.classList.toggle('hidden');

            // If the toast is now hidden, remember that for this session
            try {
